-- W03: immutable questionnaires, owner-only drafts/results; no automatic map mutation.
do $$ begin if not exists(select 1 from feture_seed.environment where singleton and project_ref='anrhayozrhrmiwexmbhw' and stage='prelaunch') then raise exception 'feture_prelaunch_required'; end if; end $$;
create function public.feture_test_definition_valid(d jsonb) returns boolean
language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare dim jsonb;q jsonb;o jsonb;ids text[]:=array[]::text[];qids text[]:=array[]::text[];oids text[];idx integer;k text;
begin
 if jsonb_typeof(d) is distinct from 'object' or not(d ?& array['id','title','description','dimensions','questions']) or (select count(*)<>5 from jsonb_object_keys(d)) or octet_length(d::text)>28000 then return false;end if;
 if jsonb_typeof(d->'id') is distinct from 'string' or (d->>'id') !~ '^[a-z][a-z0-9-]{0,47}$' then return false;end if;
 for k in select unnest(array['title','description']) loop if jsonb_typeof(d->k) is distinct from 'string' or char_length(btrim(d->>k))=0 or char_length(d->>k)>(case k when 'title' then 160 else 1200 end) or (d->>k) ~ '[[:cntrl:]]' then return false;end if;end loop;
 if jsonb_typeof(d->'dimensions') is distinct from 'array' or jsonb_typeof(d->'questions') is distinct from 'array' then return false;end if;
 if jsonb_array_length(d->'dimensions') not between 1 and 4 or jsonb_array_length(d->'questions') not between 6 and 12 then return false;end if;
 for dim in select value from jsonb_array_elements(d->'dimensions') loop
  if jsonb_typeof(dim) is distinct from 'object' or not(dim ?& array['id','title','low','mid','high']) or (select count(*)<>5 from jsonb_object_keys(dim)) or jsonb_typeof(dim->'id') is distinct from 'string' or (dim->>'id') !~ '^[a-z][a-z0-9-]{0,47}$' or (dim->>'id')=any(ids) then return false;end if;
  for k in select unnest(array['title','low','mid','high']) loop if jsonb_typeof(dim->k) is distinct from 'string' or char_length(btrim(dim->>k))=0 or char_length(dim->>k)>(case k when 'title' then 120 else 800 end) or (dim->>k) ~ '[[:cntrl:]]' then return false;end if;end loop;
  ids:=array_append(ids,dim->>'id');
 end loop;
 for q in select value from jsonb_array_elements(d->'questions') loop
  if jsonb_typeof(q) is distinct from 'object' or not(q ?& array['id','prompt','dimension','kind','options']) or (select count(*)<>5 from jsonb_object_keys(q)) or jsonb_typeof(q->'id') is distinct from 'string' or (q->>'id') !~ '^[a-z][a-z0-9-]{0,47}$' or (q->>'id')=any(qids) or jsonb_typeof(q->'dimension') is distinct from 'string' or jsonb_typeof(q->'kind') is distinct from 'string' or not((q->>'dimension')=any(ids)) or (q->>'kind') not in ('single','multi','scale') then return false;end if;
  if jsonb_typeof(q->'prompt') is distinct from 'string' or char_length(btrim(q->>'prompt'))=0 or char_length(q->>'prompt')>600 or (q->>'prompt') ~ '[[:cntrl:]]' or jsonb_typeof(q->'options') is distinct from 'array' then return false;end if;
  if jsonb_array_length(q->'options') not between 2 and 6 or q->>'kind'='scale' and jsonb_array_length(q->'options')<>5 then return false;end if;
  qids:=array_append(qids,q->>'id');oids:=array[]::text[];idx:=0;
  for o in select value from jsonb_array_elements(q->'options') loop
   if jsonb_typeof(o) is distinct from 'object' or not(o ?& array['id','label','score']) or (select count(*)<>3 from jsonb_object_keys(o)) or jsonb_typeof(o->'id') is distinct from 'string' or (o->>'id') !~ '^[a-z][a-z0-9-]{0,47}$' or (o->>'id')=any(oids) or jsonb_typeof(o->'label') is distinct from 'string' or char_length(btrim(o->>'label'))=0 or char_length(o->>'label')>240 or (o->>'label') ~ '[[:cntrl:]]' then return false;end if;
   if jsonb_typeof(o->'score') is distinct from 'number' or (o->>'score') !~ '^[0-4]$' or q->>'kind'='scale' and (o->>'score')::integer<>idx then return false;end if;
   oids:=array_append(oids,o->>'id');idx:=idx+1;
  end loop;
 end loop;
 for k in select unnest(ids) loop if (select count(*) from jsonb_array_elements(d->'questions') as qq(value) where qq.value->>'dimension'=k)<2 then return false;end if;end loop;
 return true;
exception when others then return false;
end $$;
create function public.feture_test_answers_valid(d jsonb,a jsonb) returns boolean
language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare k text;v jsonb;q jsonb;
begin
 if jsonb_typeof(a) is distinct from 'object' or (select count(*)>12 from jsonb_object_keys(a)) then return false;end if;
 for k,v in select * from jsonb_each(a) loop
  select value into q from jsonb_array_elements(d->'questions') where value->>'id'=k;
  if q is null then return false;end if;
  if v='null'::jsonb then continue;end if;
  if jsonb_typeof(v) is distinct from 'array' then return false;end if;
  if jsonb_array_length(v)<1 or jsonb_array_length(v)>6 or (q->>'kind'<>'multi' and jsonb_array_length(v)<>1) or (select count(distinct value)<>jsonb_array_length(v) from jsonb_array_elements(v)) then return false;end if;
  if exists(select 1 from jsonb_array_elements(v) s where jsonb_typeof(s) is distinct from 'string' or not exists(select 1 from jsonb_array_elements(q->'options') o where o->>'id'=s#>>'{}')) then return false;end if;
 end loop;return true;
exception when others then return false;
end $$;
-- Each answered question contributes equally. Multi-select uses the mean of its selected weights.
-- At least half the questions in a dimension must be answered for interpretation; skipped != zero.
create function public.feture_test_score(d jsonb,a jsonb) returns jsonb
language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare dim jsonb;q jsonb;v jsonb;n integer;total integer;answered integer:=0;sum_score numeric;mean_score numeric;level text;result jsonb:='[]';evidence jsonb;question_score numeric;
begin
 if not public.feture_test_definition_valid(d) or not public.feture_test_answers_valid(d,a) then raise exception 'invalid_test_data';end if;
 for dim in select value from jsonb_array_elements(d->'dimensions') loop
  n:=0;total:=0;sum_score:=0;evidence:='[]';
  for q in select value from jsonb_array_elements(d->'questions') where value->>'dimension'=dim->>'id' loop
   total:=total+1;v:=a->(q->>'id');if v is null or v='null'::jsonb then continue;end if;
   select avg((o->>'score')::numeric) into question_score from jsonb_array_elements(q->'options') o where v ? (o->>'id');
   n:=n+1;sum_score:=sum_score+question_score;evidence:=evidence||jsonb_build_array(q->>'id');
  end loop;
  answered:=answered+n;mean_score:=case when n>=ceil(total/2.0) then round(sum_score/n,2) else null end;
  level:=case when mean_score is null then 'insufficient' when mean_score<1.5 then 'low' when mean_score<2.75 then 'mid' else 'high' end;
  result:=result||jsonb_build_array(jsonb_build_object('id',dim->>'id','answered',n,'total',total,'average',mean_score,'level',level,'interpretation',case when level='insufficient' then 'Пока мало ответов для вывода. Можно вернуться к этим вопросам позже.' else dim->>level end,'questionIds',evidence));
 end loop;
 return jsonb_build_object('answered',answered,'total',jsonb_array_length(d->'questions'),'dimensions',result);
end $$;
create table public.feture_test_drafts (
 test_id text primary key check(test_id ~ '^[a-z][a-z0-9-]{0,47}$'),definition jsonb not null check(public.feture_test_definition_valid(definition) and definition->>'id'=test_id),revision bigint not null check(revision between 1 and 9007199254740991),current_version uuid,updated_at timestamptz not null default clock_timestamp());
create table public.feture_test_versions (
 id uuid primary key default gen_random_uuid(),test_id text not null references public.feture_test_drafts(test_id),draft_revision bigint not null check(draft_revision>0),definition jsonb not null check(public.feture_test_definition_valid(definition) and definition->>'id'=test_id),published_at timestamptz not null default clock_timestamp(),unique(test_id,draft_revision));
alter table public.feture_test_drafts add constraint feture_test_current_fk foreign key(current_version) references public.feture_test_versions(id);
create table public.feture_test_attempts (
 id uuid primary key default gen_random_uuid(),account_hash text not null references public.feture_profiles(account_hash) on delete cascade,test_id text not null references public.feture_test_drafts(test_id),version_id uuid not null references public.feture_test_versions(id),status text not null check(status in ('draft','completed','deleted')),answers jsonb not null default '{}',position integer not null default 0 check(position between 0 and 11),revision bigint not null default 1 check(revision between 1 and 9007199254740991),result jsonb,updated_at timestamptz not null default clock_timestamp(),check(jsonb_typeof(answers)='object'),check((status='completed')=(result is not null)),check(status<>'deleted' or answers='{}'::jsonb));
create unique index feture_test_one_draft on public.feture_test_attempts(account_hash,test_id) where status='draft';
create index feture_test_owner_history on public.feture_test_attempts(account_hash,updated_at desc,id desc) where status<>'deleted';
create index feture_test_attempt_version on public.feture_test_attempts(version_id);
create index feture_test_attempt_test on public.feture_test_attempts(test_id);
create index feture_test_draft_current on public.feture_test_drafts(current_version);
create table public.feture_test_operations (
 account_hash text not null references public.feture_profiles(account_hash) on delete cascade,operation_id uuid not null,payload_hash text not null check(payload_hash ~ '^[a-f0-9]{64}$'),attempt_id uuid not null,primary key(account_hash,operation_id));
create function public.feture_test_version_dto(v public.feture_test_versions) returns jsonb language sql stable security invoker set search_path=pg_catalog as $$ select jsonb_build_object('id',v.id,'testId',v.test_id,'revision',v.draft_revision,'definition',v.definition,'publishedAt',v.published_at); $$;
create function public.feture_test_attempt_dto(a public.feture_test_attempts) returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select jsonb_build_object('id',a.id,'version',public.feture_test_version_dto(v),'status',a.status,'answers',a.answers,'position',a.position,'revision',a.revision,'result',a.result,'updatedAt',a.updated_at) from public.feture_test_versions v where v.id=a.version_id;
$$;
create function public.feture_test_admin(p_command jsonb) returns jsonb
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare act text:=p_command->>'action';d public.feture_test_drafts;v public.feture_test_versions;tid text;expected bigint;def jsonb;items jsonb;
begin
 if act='feture.tests.list' then
  select coalesce(jsonb_agg(jsonb_build_object('testId',test_id,'definition',definition,'revision',revision,'currentVersion',current_version) order by test_id),'[]') into items from public.feture_test_drafts;
  return jsonb_build_object('ok',true,'drafts',items);
 end if;
 if act not in ('feture.tests.save','feture.tests.publish','feture.tests.retire') or jsonb_typeof(p_command) is distinct from 'object' then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 def:=p_command->'definition';tid:=case when act='feture.tests.save' then def->>'id' else p_command->>'testId' end;
 expected:=(case when act='feture.tests.save' then p_command->>'expectedRevision' else p_command->>'revision' end)::bigint;
 if tid is null or tid !~ '^[a-z][a-z0-9-]{0,47}$' or expected is null or expected<0 or expected>=9007199254740991 then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 perform pg_advisory_xact_lock(hashtextextended('feture-test-definition:'||tid,0));
 select * into d from public.feture_test_drafts where test_id=tid for update;
 if act='feture.tests.save' then
  if not public.feture_test_definition_valid(def) then return jsonb_build_object('ok',false,'error','invalid_request');end if;
  if coalesce(d.revision,0)<>expected then return jsonb_build_object('ok',false,'error','revision_conflict');end if;
  if d.test_id is null and (select count(*) from public.feture_test_drafts)>=30 then return jsonb_build_object('ok',false,'error','test_limit');end if;
  insert into public.feture_test_drafts(test_id,definition,revision) values(tid,def,expected+1) on conflict(test_id) do update set definition=excluded.definition,revision=excluded.revision,updated_at=clock_timestamp();
  return jsonb_build_object('ok',true,'revision',expected+1);
 end if;
 if d.test_id is null or d.revision<>expected then return jsonb_build_object('ok',false,'error','revision_conflict');end if;
 if act='feture.tests.retire' then update public.feture_test_drafts set current_version=null where test_id=tid;return jsonb_build_object('ok',true);end if;
 if p_command->'reviewed' is distinct from 'true'::jsonb then return jsonb_build_object('ok',false,'error','review_required');end if;
 select * into v from public.feture_test_versions where test_id=tid and draft_revision=expected;
 if v.id is null then insert into public.feture_test_versions(test_id,draft_revision,definition) values(tid,expected,d.definition) returning * into v;end if;
 update public.feture_test_drafts set current_version=v.id where test_id=tid;
 return jsonb_build_object('ok',true,'version',public.feture_test_version_dto(v));
exception when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('ok',false,'error','invalid_request');
end $$;
create function public.feture_test_command(p_owner text,p_command jsonb) returns jsonb
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare act text:=p_command->>'action';op uuid;aid uuid;expected bigint;a public.feture_test_attempts;v public.feture_test_versions;r public.feture_test_operations;digest text;tid text;items jsonb;answer_data jsonb;pos integer;retry boolean:=false;
begin
 if p_owner is null or p_owner !~ '^[a-f0-9]{32}$' or jsonb_typeof(p_command) is distinct from 'object' or act is null or act not in ('tests.list','tests.start','tests.read','tests.save','tests.complete','tests.delete') then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 perform pg_advisory_xact_lock(hashtextextended('feture-tests-owner:'||p_owner,0));
 if act='tests.list' then
  select coalesce(jsonb_agg(public.feture_test_version_dto(t) order by t.test_id),'[]') into items from public.feture_test_versions t join public.feture_test_drafts d on d.current_version=t.id;
  return jsonb_build_object('ok',true,'versions',items,'attempts',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'testId',x.test_id,'title',x.definition->>'title','status',x.status,'revision',x.revision,'updatedAt',x.updated_at) order by x.updated_at desc,x.id desc) from (select aa.id,aa.test_id,aa.status,aa.revision,aa.updated_at,vv.definition from public.feture_test_attempts aa join public.feture_test_versions vv on vv.id=aa.version_id where aa.account_hash=p_owner and aa.status<>'deleted' order by aa.updated_at desc,aa.id desc limit 100) x),'[]'));
 end if;
 if act='tests.read' then
  select * into a from public.feture_test_attempts where id=(p_command->>'attemptId')::uuid and account_hash=p_owner and status<>'deleted';
  if a.id is null then return jsonb_build_object('ok',false,'error','resource_not_found');end if;return jsonb_build_object('ok',true,'attempt',public.feture_test_attempt_dto(a));
 end if;
 op:=(p_command->>'operationId')::uuid;if op is null then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 digest:=encode(sha256(convert_to(p_command::text,'UTF8')),'hex');
 select * into r from public.feture_test_operations where account_hash=p_owner and operation_id=op;
 if r.operation_id is not null then
  if r.payload_hash<>digest then return jsonb_build_object('ok',false,'error','operation_conflict');end if;
  select * into a from public.feture_test_attempts where id=r.attempt_id and account_hash=p_owner;
  if a.id is null or a.status='deleted' then return case when act='tests.delete' then jsonb_build_object('ok',true,'deleted',true) else jsonb_build_object('ok',false,'error','resource_not_found') end;end if;
  return jsonb_build_object('ok',true,'attempt',public.feture_test_attempt_dto(a),'replayed',true);
 end if;
 if act='tests.start' then
  tid:=p_command->>'testId';
  select * into a from public.feture_test_attempts where account_hash=p_owner and test_id=tid and status='draft';
  if a.id is null then
   select t.* into v from public.feture_test_versions t join public.feture_test_drafts d on d.current_version=t.id where d.test_id=tid;
   if v.id is null then return jsonb_build_object('ok',false,'error','resource_not_found');end if;
   if (select count(*) from public.feture_test_attempts where account_hash=p_owner and status<>'deleted')>=100 then return jsonb_build_object('ok',false,'error','test_limit');end if;
   insert into public.feture_profiles(account_hash,display_name) values(p_owner,'') on conflict(account_hash) do nothing;
   insert into public.feture_test_attempts(account_hash,test_id,version_id,status) values(p_owner,tid,v.id,'draft') returning * into a;
  end if;
 else
  aid:=(p_command->>'attemptId')::uuid;expected:=(p_command->>'expectedRevision')::bigint;
  select * into a from public.feture_test_attempts where id=aid and account_hash=p_owner and status<>'deleted' for update;
  if a.id is null then return jsonb_build_object('ok',false,'error','resource_not_found');end if;
  if expected is null or expected<1 or expected>=9007199254740991 then return jsonb_build_object('ok',false,'error','invalid_request');end if;
  if a.revision<>expected then return jsonb_build_object('ok',false,'error','revision_conflict');end if;
  if act='tests.delete' then
   update public.feture_test_attempts set status='deleted',answers='{}',result=null,revision=revision+1,updated_at=clock_timestamp() where id=a.id returning * into a;
  else
   if a.status='completed' then return jsonb_build_object('ok',false,'error','attempt_completed');end if;
   select * into v from public.feture_test_versions where id=a.version_id;
   answer_data:=p_command->'answers';pos:=(p_command->>'position')::integer;
   if not public.feture_test_answers_valid(v.definition,answer_data) or pos is null or pos<0 or pos>=jsonb_array_length(v.definition->'questions') then return jsonb_build_object('ok',false,'error','invalid_request');end if;
   if act='tests.complete' and exists(select 1 from jsonb_array_elements(v.definition->'questions') q where not(answer_data ? (q->>'id'))) then return jsonb_build_object('ok',false,'error','answers_incomplete');end if;
   update public.feture_test_attempts set answers=answer_data,position=pos,revision=revision+1,updated_at=clock_timestamp(),status=case when act='tests.complete' then 'completed' else 'draft' end,result=case when act='tests.complete' then public.feture_test_score(v.definition,answer_data) else null end where id=a.id returning * into a;
  end if;
 end if;
 insert into public.feture_test_operations(account_hash,operation_id,payload_hash,attempt_id) values(p_owner,op,digest,a.id);
 if act='tests.delete' then return jsonb_build_object('ok',true,'deleted',true);end if;
 return jsonb_build_object('ok',true,'attempt',public.feture_test_attempt_dto(a),'replayed',retry);
exception when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('ok',false,'error','invalid_request');
end $$;
alter table public.feture_test_drafts enable row level security;
alter table public.feture_test_versions enable row level security;
alter table public.feture_test_attempts enable row level security;
alter table public.feture_test_operations enable row level security;
revoke all on public.feture_test_drafts,public.feture_test_versions,public.feture_test_attempts,public.feture_test_operations from public,anon,authenticated,service_role;
grant select,insert,update on public.feture_test_drafts,public.feture_test_attempts to service_role;
grant select,insert on public.feture_test_versions,public.feture_test_operations to service_role;
grant delete on public.feture_test_attempts,public.feture_test_operations to service_role;
revoke all on function public.feture_test_definition_valid(jsonb),public.feture_test_answers_valid(jsonb,jsonb),public.feture_test_score(jsonb,jsonb),public.feture_test_admin(jsonb),public.feture_test_command(text,jsonb),public.feture_test_version_dto(public.feture_test_versions),public.feture_test_attempt_dto(public.feture_test_attempts) from public,anon,authenticated;
grant execute on function public.feture_test_definition_valid(jsonb),public.feture_test_answers_valid(jsonb,jsonb),public.feture_test_score(jsonb,jsonb),public.feture_test_admin(jsonb),public.feture_test_command(text,jsonb),public.feture_test_version_dto(public.feture_test_versions),public.feture_test_attempt_dto(public.feture_test_attempts) to service_role;

-- Initial editorial drafts only. Publishing requires the explicit reviewed admin action.
do $seed$ declare r jsonb; begin
 r:=public.feture_test_admin('{"action":"feture.tests.save","definition":{"id":"dynamics","title":"Роли и динамика","description":"Как тебе комфортнее распределять инициативу и договорённости. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"initiative","title":"Инициатива","low":"Тебе может быть комфортнее откликаться на предложения. Это не обязанность оставаться в одной роли.","mid":"Похоже, инициатива зависит от ситуации. Можно обсудить, когда хочется предлагать, а когда — откликаться.","high":"В ответах заметен интерес проявлять инициативу. Это не даёт права решать за другого человека."},{"id":"agreement","title":"Ясность договорённостей","low":"Тебе может подходить меньше заранее заданных правил. Даже при спонтанности нужно обсуждать согласие и право остановиться.","mid":"Тебе может подходить сочетание договорённостей и свободы. Полезно заранее назвать то, что менять нельзя.","high":"В ответах важна ясность ожиданий. Подробные договорённости могут помогать комфорту, но не заменяют согласие в моменте."}],"questions":[{"id":"initiative-1","prompt":"Мне нравится предлагать, как провести время вместе.","dimension":"initiative","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"initiative-2","prompt":"Мне комфортно первым начинать разговор о желаниях.","dimension":"initiative","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"initiative-3","prompt":"Мне интересно задавать направление совм