e":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"agreement-4","prompt":"Перед новым опытом мне хочется обсудить возможные изменения плана.","dimension":"agreement","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]}]},"expectedRevision":0}'::jsonb);if r->'ok' is distinct from 'true'::jsonb then raise exception 'feture_test_seed_failed';end if;
 r:=public.feture_test_admin('{"action":"feture.tests.save","definition":{"id":"closeness","title":"Близость и пространство","description":"Что помогает ощущать связь, сохраняя комфортную дистанцию. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"connection","title":"Эмоциональная связь","low":"В ответах сейчас меньше потребности в частом эмоциональном обмене. Можно искать удобные способы связи без давления.","mid":"Похоже, степень близости зависит от ситуации. Стоит обсудить, какие проявления поддержки подходят именно тебе.","high":"В ответах заметна потребность в эмоциональной связи. Другой человек может проявлять её иначе; лучше назвать конкретные ожидания."},{"id":"space","title":"Личное пространство","low":"Сейчас отдельное время может быть менее значимым для тебя. Это не означает, что у тебя нет границ.","mid":"Похоже, тебе нужен гибкий баланс совместного и личного времени. Его можно пересматривать.","high":"В ответах важно личное пространство. Можно договориться о времени на себя без трактовки его как отвержения."}],"questions":[{"id":"connection-1","prompt":"Мне важно регулярно делиться переживаниями с близким человеком.","dimension":"connection","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"connection-2","prompt":"Тёплые слова помогают мне чувствовать связь.","dimension":"connection","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"connection-3","prompt":"Мне хочется обсуждать, как меняются наши отношения.","dimension":"connection","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"connection-4","prompt":"В сложный день я хочу иметь возможность попросить поддержки.","dimension":"connection","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"space-1","prompt":"Мне нужно время без общения, даже когда отношения хорошие.","dimension":"space","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"space-2","prompt":"Я хочу сохранять отдельные занятия и интересы.","dimension":"space","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"space-3","prompt":"Мне комфортнее заранее обсудить частоту общения.","dimension":"space","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"space-4","prompt":"Мне важно самостоятельно выбирать, чем делиться сегодня.","dimension":"space","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]}]},"expectedRevision":0}'::jsonb);if r->'ok' is distinct from 'true'::jsonb then raise exception 'feture_test_seed_failed';end if;
 r:=public.feture_test_admin('{"action":"feture.tests.save","definition":{"id":"sensations","title":"Ощущения и любопытство","description":"Какие условия помогают исследовать ощущения без обязательства пробовать что-либо. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"novelty","title":"Новизна","low":"В ответах сейчас ближе знакомые ощущения. Нет необходимости расширять опыт ради чьих-то ожиданий.","mid":"Интерес к новизне зависит от условий. Можно начать с разговора или наблюдения без обязательства действовать.","high":"В ответах есть любопытство к новому. Оно не означает готовности к любой теме и не отменяет отдельных границ."},{"id":"predictability","title":"Предсказуемость","low":"В ответах меньше потребности в подготовке. Полезно всё равно обозначать согласие, ограничения и возможность остановки.","mid":"Тебе может подходить немного подготовки и возможность менять план. Стоит назвать условия, которые помогают расслабиться.","high":"В ответах важны подготовка и предсказуемость. Можно заранее обсудить обстановку и темп без обязанности продолжать."}],"questions":[{"id":"novelty-1","prompt":"Мне интересно узнавать о незнакомых ощущениях.","dimension":"novelty","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"novelty-2","prompt":"Мне нравится рассматривать разные способы совместного отдыха.","dimension":"novelty","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"novelty-3","prompt":"Я хочу иметь возможность попробовать новое и передумать.","dimension":"novelty","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"novelty-4","prompt":"Мне интересно обсуждать фантазии, даже если я не собираюсь их воплощать.","dimension":"novelty","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"predictability-1","prompt":"Мне спокойнее заранее понимать, как будет устроен новый опыт.","dimension":"predictability","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"predictability-2","prompt":"Для комфорта мне важно выбрать подходящее место и время.","dimension":"predictability","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"predictability-3","prompt":"Мне помогает начинать с небольших понятных шагов.","dimension":"predictability","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"predictability-4","prompt":"Мне хочется знать, что пауза не вызовет обиды или давления.","dimension":"predictability","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]}]},"expectedRevision":0}'::jsonb);if r->'ok' is distinct from 'true'::jsonb then raise exception 'feture_test_seed_failed';end if;
 r:=public.feture_test_admin('{"action":"feture.tests.save","definition":{"id":"boundaries","title":"Границы и приватность","description":"Условия общения и раскрытия сведений. Ответы не устанавливают и не отменяют твои реальные границы. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"discussion","title":"Обсуждение комфорта","low":"В ответах меньше предпочтения подробно обсуждать условия. При этом любое действие требует отдельного согласия; молчание не считается разрешением.","mid":"Может подходить короткое обсуждение важных условий. Уточнять их можно в любой момент.","high":"В ответах важен явный разговор о комфорте. Можно заранее согласовать слова для паузы и остановки."},{"id":"privacy","title":"Выбор раскрытия","low":"Сейчас выборочная открытость может быть комфортнее. Результат ничего не публикует: отдельные сведения раскрываешь только ты.","mid":"Степень открытости может зависеть от темы и человека. Удобно выбирать сведения по отдельности.","high":"В ответах важно контролировать раскрытие. Можно выдавать частичный доступ на срок и отзывать его."}],"questions":[{"id":"discussion-1","prompt":"Мне удобно словами обсуждать, что подходит, а что нет.","dimension":"discussion","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"discussion-2","prompt":"Я хочу, чтобы изменения плана сначала обсуждались.","dimension":"discussion","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"discussion-3","prompt":"Мне важно регулярно сверяться с самочувствием друг друга.","dimension":"discussion","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"discussion-4","prompt":"Мне легче говорить о желаниях, когда отказ принимают спокойно.","dimension":"discussion","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"privacy-1","prompt":"Мне важно отдельно выбирать, кто увидит мои личные ответы.","dimension":"privacy","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"privacy-2","prompt":"Я хочу согласовывать публикацию совместных историй или фото.","dimension":"privacy","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"privacy-3","prompt":"Мне спокойнее, когда разрешение на просмотр можно отозвать.","dimension":"privacy","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","lab