 r:=public.feture_test_admin('{"action":"feture.tests.save","definition":{"id":"relationships","title":"Формат отношений","description":"Какие договорённости и способы связи хочется обсудить. Здесь не определяется тип личности. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"structure","title":"Определённость формата","low":"В ответах сейчас ближе гибкость формата. Разные ожидания всё равно стоит обсуждать напрямую.","mid":"Может быть комфортно постепенно уточнять формат. Можно договориться о времени следующего разговора.","high":"В ответах важна определённость. Полезно назвать ожидания конкретно и проверить, совпадают ли они у всех участников."},{"id":"independence","title":"Самостоятельность","low":"Сейчас тебе может быть ближе много совместных решений. Это не отменяет права на собственные желания и отказ.","mid":"Похоже, тебе нужен баланс общих и личных решений. Его можно обсудить по конкретным ситуациям.","high":"В ответах важна самостоятельность. Можно договориться, какие решения общие, а какие каждый принимает сам."}],"questions":[{"id":"structure-1","prompt":"Мне хочется понимать, как мы называем наши отношения.","dimension":"structure","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"structure-2","prompt":"Мне важно обсуждать ожидания относительно других связей.","dimension":"structure","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"structure-3","prompt":"Мне удобно договари